from __future__ import annotations

import time
from dataclasses import dataclass, field
from typing import Any

from hbllm.hcir.grounding.contracts.enums import ActionLifecycleState
from hbllm.hcir.grounding.contracts.references import GroundedRef


@dataclass(frozen=True)
class SymbolicActionIntent:
    """A symbolic action generated by the HCIR OFC/BA10 planner.

    Contains pure cognitive intent without actuator specifics.
    """

    intent_id: str
    action_type: str
    target_ref: GroundedRef
    parameters: dict[str, Any] = field(default_factory=dict)
    preconditions: tuple[str, ...] = field(default_factory=tuple)
    expected_outcomes: tuple[str, ...] = field(default_factory=tuple)
    created_at: float = field(default_factory=time.time)

    def __post_init__(self) -> None:
        if not self.intent_id:
            raise ValueError("intent_id must be non-empty")
        if not self.action_type:
            raise ValueError("action_type must be non-empty")
        if not isinstance(self.target_ref, GroundedRef):
            raise TypeError(f"target_ref must be GroundedRef, got {type(self.target_ref)}")


@dataclass(frozen=True)
class RenderedActionPayload:
    """The output of a pure Renderer (Language, Kinematics, GUI).

    Contains the executable payload ready for validation by ActionValidationGateway.
    """

    payload_id: str
    intent_id: str
    renderer_name: str
    execution_channel: str
    payload_data: dict[str, Any]
    target_entity_version: int = 0
    estimated_duration_s: float = 0.0
    created_at: float = field(default_factory=time.time)


@dataclass(frozen=True)
class ActionValidationResult:
    """The decision emitted by ActionValidationGateway prior to dispatch."""

    payload_id: str
    is_authorized: bool
    rejection_reasons: tuple[str, ...] = field(default_factory=tuple)
    safety_margin: float = 1.0
    requires_human_confirmation: bool = False
    reversibility_verified: bool = True
    validated_at: float = field(default_factory=time.time)


@dataclass(frozen=True)
class ActionExecutionRecord:
    """Complete lifecycle audit trace for an executed action."""

    intent_id: str
    payload_id: str
    state: ActionLifecycleState
    dispatched_at: float = 0.0
    reported_at: float = 0.0
    verified_at: float = 0.0
    outcome_verified: bool = False
    surprise_detected: bool = False
    error_message: str = ""
